def _load_embedded():
    import base64 as _b64
    source = _b64.b64decode(_V50_SOURCE_B64).decode("utf-8")
    namespace = {"__name__": "v92_frozen_v50"}
    exec(compile(source, "<embedded v50_agent.py>", "exec"), namespace)  # noqa: S102
    return namespace


_v50_ns = _load_embedded()
_v50_agent = _v50_ns["agent"]



def _v92_shed_total(private):
    return sum((private.get("shed") or {}).values())


def _v92_carried_total(private):
    return sum(
        sum((inv or {}).values())
        for inv in (private.get("inventories") or [])
    )


def _v92_live_animals(farm):
    return sum(
        1
        for row in farm.get("tiles") or []
        for tile in row
        if isinstance(tile, dict) and tile.get("animal")
    )


def _v92_buy_units(orders, item):
    return sum(int(o[2]) for o in orders if len(o) > 2 and o[0] == "BUY_PRODUCT" and o[1] == item)


def _v92_apply(obs, action):
    day = int(obs.get("day", 0) or 0)
    hour = int(obs.get("hour", 0) or 0)
    if day != GUARD_DAY or hour != GUARD_HOUR:
        return action

    seat = int(obs.get("player", 0) or 0)
    farms = obs.get("farms") or []
    if seat >= len(farms):
        return action
    farm = farms[seat]
    private = obs.get("private") or {}

    orders = list(action.get("market") or [])
    wheat_buys = _v92_buy_units(orders, "WHEAT")
    fert_buys = _v92_buy_units(orders, "FERTILIZER")
    if wheat_buys <= 0 and fert_buys <= 0:
        return action

    shed_now = _v92_shed_total(private)
    carried_now = _v92_carried_total(private)
    projected = shed_now + carried_now + wheat_buys + fert_buys + HARVEST_ALLOWANCE
    if projected <= SHED_CAPACITY:
        return action

    # Reserve floor, expressed as units that must REMAIN BOUGHT rather than units
    # left unpurchased. An earlier version of this guard used a per-animal wheat
    # floor, which on the audited state (16 animals, a 16-unit wheat buy) forbade
    # trimming wheat at all and left the overflow uncorrectable. The binding
    # reserve is what the farm still holds in the shed: shed wheat and shed
    # fertilizer are what feed the next day, not this turn's order quantity.
    shed = private.get("shed") or {}
    shed_wheat = int(shed.get("WHEAT", 0) or 0)
    shed_fert = int(shed.get("FERTILIZER", 0) or 0)
    # Keep buying at least the smaller of what was ordered and a small floor, so
    # the farm never abandons feed/soil entirely, and keep existing shed stock.
    wheat_keep = min(wheat_buys, max(0, min(shed_wheat, wheat_buys)))
    fert_keep = min(fert_buys, MIN_FERT_RESERVE)

    new_wheat = wheat_buys
    new_fert = min(fert_buys, MAX_FERT_BUY)
    if new_fert < fert_keep:
        new_fert = fert_keep

    # Recompute projection with the adjusted buys and trim in bulk, not one unit
    # per pass: a one-unit-per-pass loop cannot cover a double-digit excess.
    def projected(wheat_qty, fert_qty):
        return shed_now + carried_now + wheat_qty + fert_qty + HARVEST_ALLOWANCE

    guard_passes = 0
    while projected(new_wheat, new_fert) > SHED_CAPACITY and guard_passes < 32:
        guard_passes += 1
        # Trim fertilizer first (cheapest per unit), then wheat, but never below
        # the floors.
        if new_fert > fert_keep:
            new_fert -= 1
        elif new_wheat > wheat_keep:
            new_wheat -= 1
        else:
            break

    if new_wheat == wheat_buys and new_fert == fert_buys:
        return action

    new_orders = []
    for order in orders:
        if len(order) > 2 and order[0] == "BUY_PRODUCT" and order[1] == "FERTILIZER":
            if new_fert > 0:
                new_orders.append(["BUY_PRODUCT", "FERTILIZER", new_fert])
        elif len(order) > 2 and order[0] == "BUY_PRODUCT" and order[1] == "WHEAT":
            if new_wheat > 0:
                new_orders.append(["BUY_PRODUCT", "WHEAT", new_wheat])
        else:
            new_orders.append(list(order))

    action = _v92_copy.deepcopy(action)
    action["market"] = new_orders
    return action


def _v92_entrypoint(obs, configuration=None):
    return _v92_apply(obs, _v50_agent(obs, configuration))


def _kaggle_submission_entrypoint(obs, configuration=None):
    return _v92_entrypoint(obs, configuration)


"""V98-R1: buy the extra cow ONLY into the tape's own animal-placement window.

Revision of the first V98 candidate, which the assignment permits once, after a diagnosis.

THE DIAGNOSIS THAT FORCED THIS REVISION
---------------------------------------
The first V98 candidate appended ["BUY_ANIMAL","COW",1] on day 6 and bought 13 cows for
$5,200. It placed NONE of them. The cow lands in the shed, and PLACE (engine 377-392)
only works when an actor is CARRYING the animal, which requires a prior PICKUP from a
shed-adjacent tile (engine 358-375) and then a walk to a free PASTURE. The frozen tape
performs that dance for its own herd on a fixed schedule:

    PICKUP/PLACE by day (measured, 14 official replays, this seed):
      d0 COW x2, SHEEP x2 | d2 COW | d3 COW | d6 SHEEP x2 | d7 COW x2
      d8 SHEEP x2 | d9 SHEEP | d10 SHEEP x3 | d11 SHEEP

Buying a cow on day 6 added cash cost and a shed-slot liability with no placement path,
because day 6's animal work is a SHEEP errand, not a COW errand. Every extra cow was
deleted by the end-of-day drop.

THE REVISION
------------
Buy the cow only on a turn where the FROZEN ROUTE ITSELF is already issuing an animal
PICKUP, so the cow is picked up by the walk that is already happening. On such a turn the
tape is standing at a shed-adjacent tile about to collect an animal, so a cow bought now
is collected on the same walk and carried to a structure on the same errand.

This is the only version of the idea that can work without borrowing a worker, which V97
measured as catastrophic (-89,887): it adds NO worker-time demand at all. It only changes
what the already-running errand carries.

Concretely, on a turn where the recorded action contains a PICKUP of an animal, and the
market list has room, and the shed has headroom, append ["BUY_ANIMAL","COW",1].

WHY THIS IS SAFE AND BOUNDED
-----------------------------
  * It fires only on the tape's own animal-collection turns, so the worker cost is zero.
  * It fires at most once (a latch), so at most ONE extra cow is ever bought.
  * It requires a free PASTURE to exist, so the cow has somewhere to go.
  * It requires the market list to have room, so the incumbent's own orders are untouched.
  * It requires cash above a floor that keeps the existing herd's feed funded.
  * The cow then becomes an ordinary animal: the tape's daily FEED/CARE sweep covers it,
    because that sweep visits every animal tile the farm has.

If the cow is not collected on the same errand, it costs $400 and occupies a shed slot
until the drop deletes it, which is the -$400 worst case. That is the whole downside and
it is bounded and small.
"""

import copy as _r1_copy



# Independent same-route day-6 one-for-one SHEEP -> COW intervention.
import copy as _swap_copy

def _v101_milk_sink_without_wool_route(obs):
    """Visible d6 demand: at least one MILK sink and no direct WOOL sink."""
    shops = (obs.get("town") or {}).get("unlocked_shops", [])
    return (any(s in {"PIZZA_SHOP", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP"} for s in shops)
            and "YARN_STORE" not in shops)

def _swap_apply(obs, action):
    if not isinstance(obs, dict) or not isinstance(action, dict):
        return action
    day, hour = obs.get("day"), obs.get("hour")
    out = None
    # Replace one unit in the existing day-6 two-sheep order, preserving order position.
    if day == 6 and hour == 6 and _v101_milk_sink_without_wool_route(obs):
        orders = list(action.get("market") or [])
        for i, order in enumerate(orders):
            if isinstance(order, list) and len(order) >= 3 and order[0] == "BUY_ANIMAL" and order[1] == "SHEEP" and int(order[2]) >= 2:
                out = _swap_copy.deepcopy(action)
                out["market"][i][2] = int(order[2]) - 1
                out["market"].insert(i + 1, ["BUY_ANIMAL", "COW", 1])
                action = out
                break
    # On the existing day-6 shed errand, carry the replacement cow on one sheep pickup.
    private = obs.get("private") or {}
    shed = private.get("shed") or {}
    if day == 6 and _v101_milk_sink_without_wool_route(obs) and int(shed.get("COW", 0) or 0) > 0:
        out = out or _swap_copy.deepcopy(action)
        actors = [out.get("farmer")] + list(out.get("hands") or [])
        for ai, a in enumerate(actors):
            if isinstance(a, list) and len(a) > 1 and a[0] == "PICKUP" and a[1] == "SHEEP":
                a[1] = "COW"
                if ai == 0:
                    out["farmer"] = a
                else:
                    out["hands"][ai - 1] = a
                break
    # Convert the corresponding species-specific placement for the actor carrying COW.
    if day == 6 and _v101_milk_sink_without_wool_route(obs):
        invs = private.get("inventories") or []
        out = out or _swap_copy.deepcopy(action)
        actors = [out.get("farmer")] + list(out.get("hands") or [])
        for ai, a in enumerate(actors):
            if ai < len(invs) and int((invs[ai] or {}).get("COW", 0) or 0) > 0 and isinstance(a, list) and len(a) > 1 and a[0] == "PLACE" and a[1] == "SHEEP":
                a[1] = "COW"
                if ai == 0:
                    out["farmer"] = a
                else:
                    out["hands"][ai - 1] = a
    return out if out is not None else action

def _luna_swap_entrypoint(obs, configuration=None):
    return _swap_apply(obs, _v92_entrypoint(obs, configuration))

# Last callable for Kaggle's get_last_callable loader.
_kaggle_submission_entrypoint = _luna_swap_entrypoint

